INSERT INTO public.exam_sections (id, exam_id, title, order_index) VALUES ('exam-calculus-2-2026-retake-sec-0', 'exam-calculus-2-2026-retake', '一、单选题', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, title = EXCLUDED.title, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2026-retake-s0-0', 'exam-calculus-2-2026-retake', 'exam-calculus-2-2026-retake-sec-0', 0, '曲面是（）.', '曲面 $z = \\sqrt{x^2 + y^2}$ 是（）.', '["zox平面上曲线 $z = x$ 绕 $z$ 轴旋转而成的旋转曲面","zoy平面上曲线 $z = |y|$ 绕 $z$ 轴旋转而成的旋转曲面","zox平面上曲线 $z = x$ 绕 $x$ 轴旋转而成的旋转曲面","zoy平面上曲线 $z = |y|$ 绕 $y$ 轴旋转而成的旋转曲面"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2026年5月长沙理工大学高数A（二）重修期末', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2026-retake-s0-1', 'exam-calculus-2-2026-retake', 'exam-calculus-2-2026-retake-sec-0', 0, '函数在点处偏导数存在，是它在该', '函数 $z = f(x, y)$ 在点 $(x_0, y_0)$ 处偏导数存在，是它在该点存在全微分的（）.', '["必要条件","充分条件","充分必要条件","既非充分又非必要条件"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2026年5月长沙理工大学高数A（二）重修期末', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2026-retake-s0-2', 'exam-calculus-2-2026-retake', 'exam-calculus-2-2026-retake-sec-0', 0, '设是连续函数，交换二次积分积分', '设 $f(x,y)$ 是连续函数，交换二次积分 $\\int_{1}^{e} dx \\int_{0}^{lnx} f(x,y) dy$ 积分次序的结果为（）.', '["$\\\\int_{1}^{e}dy\\\\int_{0}^{lnx}f(x,y)dx$","$\\\\int_{e^{y}}^{e}dy\\\\int_{0}^{1}f(x,y)dx$","$\\\\int_{0}^{lnx}dy\\\\int_{1}^{e}f(x,y)dx$","$\\\\int_{0}^{1}dy\\\\int_{e^{y}}^{e}f(x,y)dx$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2026年5月长沙理工大学高数A（二）重修期末', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2026-retake-s0-3', 'exam-calculus-2-2026-retake', 'exam-calculus-2-2026-retake-sec-0', 0, '二重积分的值与（）.', '二重积分 $\\iint_{D} f(x, y) \\, dx \\, dy$ 的值与（）.', '["函数 $f$ 及变量 $x, y$ 有关","区域 D 及变量 $x, y$ 无关","函数 $f$ 及区域 D 有关","函数 $f$ 无关，区域 D 有关"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2026年5月长沙理工大学高数A（二）重修期末', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2026-retake-s0-4', 'exam-calculus-2-2026-retake', 'exam-calculus-2-2026-retake-sec-0', 0, '函数项级数的收敛域是（）.', '函数项级数 $\\sum_{n=1}^{\\infty}\\frac{x^{n}}{n}$ 的收敛域是（）.', '["[-1,1]","[-1,1)","(-1,1)","(-1,1]"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2026年5月长沙理工大学高数A（二）重修期末', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
